def build(exam):
 src={r['number']:r['session'] for r in json.loads((D/f'source-exam-{exam:02}.json').read_text())}
 blueprint=next(x for x in json.loads((D/'blueprint.json').read_text())['exams'] if x['examNumber']==exam)
 questions=[]
 for number,(line,slot) in enumerate(zip(rows[exam].splitlines(),blueprint['slots']),1):
  parts=line.split('|');assert len(parts)==12,(exam,number,len(parts))
  ses,refspec,claim,prompt,a,b,c,d,explanation,rb,rc,rd=parts;ses=int(ses);assert ses==slot['session'],(exam,number,ses,slot)
  session=src[ses];refs=[]
  for spec in refspec.split(';'):
   cn,pns=spec.split(':');cl=next(x for x in session['clusters'] if x['id'].endswith('-cluster-'+cn))
   ids=[next(x['id'] for x in cl['paragraphs'] if x['id'].endswith('-p'+pn)) for pn in pns.split(',')]
   refs.append({'sessionId':session['id'],'clusterId':cl['id'],'paragraphIds':ids})
  questions.append({'number':number,'promptJa':prompt,'choicesJa':[a,b,c,d],'correctIndex':0,'explanationJa':explanation,'objectiveKey':claim,'claimJa':claim,'sourceReferences':refs,'distractorRationalesJa':[explanation,rb,rc,rd]})
 assert len(rows[exam].splitlines())==len(questions)==40
 out={'examNumber':exam,'titleJa':f'建設 学習確認試験 第{exam}回','questions':questions}
 (D/f'author-exam-{exam:02}.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
 print('Authored exam',exam,len(questions),'questions',sum(len(q['sourceReferences'])>1 for q in questions),'multi-cluster items')
for exam in [5,6]:build(exam)
